    "id": "697d5b7d4281e67fd20e8287",
    "title": "8th Annual George E Smith Memorial Car Show and Swap Meet | Mar 28th",
    "startDate": "2026-03-28T14:00:00.448Z",
    "endDate": "2026-03-28T19:00:00.448Z",
