    "source": "CCCHR",
    "city": "Virginia Beach",
    "venue": "Landstown Commons Shopping Center",
    "address": "3312 Princess Anne Road, Virginia Beach, VA, 23456",
    "description": "8th Annual George E Smith Memorial Car Show and Swap Meet Saturday, March 28 | 10a-3p Register Here Join us as we celebrate the memory of a local car enthusiast who passed away December 28, 2018. George was a vital part of the Landstown Cruise-Ins, and we are proud to remember him with an annual event. George also served on the board of the Beachcomber Corvette Club served as the president of the Car Club Council of Hampton Roads. This will be an all years, makes, and models event with awards. Beach Restomods is hosting a Swap Meet in the lot in conjunction with the show benefitting charity! Portion of proceeds will benefit a charity that George believed in, the Southeastern Food Bank. We will be accepting all non perishable food items for the food bank. Proceeds will also benefit the Car Club Council of Hampton Roads as we work on improved events for all of our attendees. This event is hosted by 757 Auto Events and the Car Club Council of Hampton Roads. Vendors: AWARDS: | 20 OUTSTANDING MODERN BUILDS | 20 OUTSTANDING CLASSIC BUILDS | BEST IN SHOW - OVERALL | BEST IN SHOW - RUNNER UP | Beachcombers Corvette Club of Virginia CHOICE | Car Club Council of Hampton Roads CHOICE | BEST CLASSIC CORVETTE | BEST MODERN CORVETTE | BEST CHEVROLET | BEST FORD | BEST GENERAL MOTORS | BEST MOPAR | BEST IMPORT | BEST TUNER | BEST JEEP | BEST TRUCK/SUV | BEST MOTORCYCLE | BEST ORPHAN | BEST CUSTOM Kid’s Choice | DVC Entertainment, LLC Choice | HEPCAT HONEYS' Choice TOP EVENT SUPPORTER | BEST REPPED CLUB Beachcombers are sponsoring: | LARGEST FOOD DONATION | LARGEST FOOD DONATION - RUNNER UP Sponsorship includes space for a 10x10 booth. ZR1 - AWARD SPONSORSHIP $300 Z06 Sponsors $150 Stingray Sponsor $100 Pre-registration saves you money! | $16 Car Show PreRegistration ($20 day of event) | $11 Bike or Motorcycle PreRegistration ($15 day of event) | $30 vendor spots 10x10 and display vehicle | $15 Non-profit space and 1 display vehicle 10:00 Registration / Show begins | 11:00 Driver’s meeting / Judging begins | 1:00 Registration Ends | 2:00 Silent Auction Ends | 2:30 Awards | 3:00 Show Ends Happening same day, same location! Swap Meet More info",
    "sourceUrl": "https://www.facebook.com/events/829821402420575/",
    "url": "https://www.ccchr.org/events/8th-annual-george-e-smith-memorial-car-show-and-swap-meet-mar-28th",
    "image": "https://images.squarespace-cdn.com/content/v1/6162287958ee4e2159a4807d/1704760732628-ODPBC0HZWSHQAMPAYD9A/George+2024.jpeg"
