    "description": "(Weekly) 2026 Wednesday Community Cruise In Wednesday, July 1st | 4-7p Located at 1317 Armory Dr., Franklin. Join our Franklin Cruise in friends and family for the First meet of the 2026 Franklin Community Cruise-In season! Weekly cruise-ins will continue each Wednesday until October. The Franklin Independence Day Celebration with the City of Franklin and Franklin Experience will be on Saturday, July 4th with fireworks and a live band. The Grand Finale will be on Saturday, October 3, 2026. Come out and enjoy rides, fun and fellowship. Looking forward to seeing everyone there.",
