    "venue": "Rosie's Lot 7",
    "address": "10515 Colonial Downs Parkway, New Kent, VA, 23124",
    "description": "[1st & 3rd fri] NK Cruisers Cruise In Friday, July 3rd | 6-9p Located at Rosie's Lot 7, 10515 Colonial Downs Pkwy., New Kent. NK Cruisers meet the 1st and 3rd Friday 6-9p or until the last person leaves (November-March). NK Cruisers, a local car enthusiast and cruise-in group bringing the car community together between Richmond and Williamsburg. The focus is New Kent, Charles City, and Lanexa but we welcome all folks from all areas. All years, makes, models, years, cars, truck, motorcycles, golf carts, boats, tractors, and trailered vehicles always welcome. Inclement weather cancels. For more information email: nkcruisers@gmail.com and NK Cruisers Facebook page for announcements and information. www.facebook.com/groups/277456353510653/",
