    "description": "(1st Sun) Cheeseburgers & Classic Car Cruise in Sunday, July 5th | 2-9pm Hosted by Farmer's Table, 13416 Benns Church Blvd., Smithfield. Cheeseburgers & Classic Cars is a family event open to all automotive enthusiast. We welcome all Classic Cars, Trucks, Motorcycles and Tractors, including show quality restorations to rusty survivors and everything in-between on the 1st Sunday of each month at Cypress creek shopping center! Bring the kids, young and old! no fees or registrations. Please do not park in the front row of the stores - thank you. For outdoor dining, Tailgate, or curbside call 757-357-1717. View Menu Order Online",
