    "description": "(2nd Thu) Team NvUS: Crews & Brews @ TGB Thursday, July 9th | 5:30-8p Located at The Garage Brewery, 1011 Eden Way N., Chesapeake. Every 2nd Thursday, Designated parking outside and one vehicle parked inside! Team NvUS is a Worldwide Car Club that was established in 2011. The team focuses on maintaining that family atmosphere amongst enthusiasts, all while showcasing quality vehicles at many High Exposure Shows and Charity Shows/Events. All Team NvUS Members are shown with an \"NvUS\" banner on their car. Virginia 757 Chapter is just one of 4 Chapters in Virginia and also one of over 200 chapters worldwide. More Info",
