    "address": "250 Visitor Center Drive, Williamsburg, VA, 23185",
    "description": "The Shine Showdown Saturday, July 18th | 10am-5pm Located at 250 Visitor Center Dr Williamsburg, VA 23185 Move in day July 17th between 12noon-7pm, vehicle must have less than a 1/4 tank of gas. The cost to register a Car/Bike is $35 and Vendor Spaces available for $150. All vehicles and bikes welcomed. Car Show judging will be based on pre-registered vehicles. Guest Speaker, DJ, and celebrity guest are invited. The mission of the SHINE SHOWDOWN is to bring together automotive enthusiasts, businesses, and innovators to celebrate excellence in vehicle presentation, craftsmanship, and protection. We aim to create a high-energy, educational, and community-driven experience that elevates the standard of car culture in Virginia and beyond. Register Here",
