    "description": "Nerds & Horsepower Saturday, July 25th | Noon-6P Located at St. George Brewing Company- 204 Challenger Way, Hampton, Va Where geek culture meets car culture! Join us at St. George Brewing Company for an exciting community event filled with awesome vehicles, unique vendors, collectibles, food, brews, and fandom fun. Explore a marketplace featuring artists, makers, collectibles, anime-inspired goods, pop culture merchandise, and more while checking out an incredible variety of cars and automotive builds. Whether you’re into horsepower, gaming, anime, comics, or just looking for a fun day out, there’s something for everyone to enjoy. Car Showcase | Vendors & Artists | Nerd Culture & Collectibles | Food & Brews | Community & Fun Cosplay Encouraged | Family Friendly | Free Admission Gather your crew and come celebrate the perfect mix of fandoms and horsepower at Nerds & Horsepower! Flyer designed by @kazarts More Info",
