    "description": "18th Annual Boulevard of Wheels Custom Car Show Saturday, September 5th | 9a-3p Located at Hackers Bar & Grille - 1532 Laskin Rd. Virginia Beach, VA. 23451 (Hilltop East) For 18 consecutive years, on Labor Day weekend, ￼the Boulevard of Wheels presented by Street Dreams Corvette Club has consistently built upon the triumph of its previous shows. Each year it’s our goal to present an event that surpasses its predecessor in excellence. Just as previous shows, this one will be consistent with our standards as far as history and tradition, but at our NEW LOCATION. The new venue will be Hackers Bar & Grille a luxury golf-themed restaurant and sports bar located at 1532 Laskin Rd. Virginia Beach, VA. 23451 (Hilltop East). This location provides a bigger, better, and bolder experience in every aspect, offering participants a unique never been done before car show experience in a convenient location. | This location will offer an accommodating show field, prominent aesthetics and a serene atmosphere. | Featuring a modern sports lounge with a focus on both leisure and entertainment. | Key Features: | •Hi-Def Golf Simulators | •Cigar Lounge | •Food & Drink | •Sports Viewing (65 TVs throughout) | •Games | This prime location is so nice that I have to say it twice-This prime location is so nice and it’s just minutes away from everything (The Oceanfront, VB Town Center, Lynnhaven Mall, Ocean Breeze Water Park, VB Aquarium) and much more. | We invite you to attend the show and | make it a memorable weekend. Our hosting hotel will be, the Doubletree 1900 Pavilion Dr. Virginia Beach, VA 23451. A special SDCC discounted rate will be offered. So come join us on (Labor Day Weekend) Saturday September 5, 2026 from 9am-3pm. Pre-registration fee $25 Day of show $30. There will be a Meet & Greet on Friday evening from 6pm-10pm at Hackers as well. Hope to see you there. More info",
    "sourceUrl": "https://www.facebook.com/events/855164203556929/",
    "url": "https://www.ccchr.org/events/18th-annual-boulevard-of-wheels-custom-car-show-sept-5",
    "image": "https://images.squarespace-cdn.com/content/v1/6162287958ee4e2159a4807d/1782341238040-1G92YBCP4T76UTOX6A2M/18th+Annual+Boulevard+of+Wheels+Custom+Car+Show.jpg"
