    "description": "15th Annual AOH Car Show Saturday, September 12th | 8a-3p Located at 4552 Princess Anne Road, Virginia Beach, VA Fund-raiser event for the Ancient Order of Hibernians, St Patrick Div1. Located at Catholic High School. Participant and audience voting for trophy-awards in all classes, participant dash-plaques for all show cars. Special Youth Judging Class #12 for all makes/models to be judged by our young people. All makes/models. DJ-Music, & food for sale on site. All proceeds are a charitable donation to the St Patrick Division AOH, a registered 501c Charity. No alcohol, no glass containers or any drugs on field, show cars should have a fire extinguisher. Registration fee: $20.00 in advance, $25.00 after 1 SEP/Day of the show. Event Contact: Mark Monaghan, jaxops1@verizon.net Register Here More Info",
    "sourceUrl": "https://aohvabeach.org/15th-annual-aoh-car-show/",
