    "venue": "Billsburg Brewery",
    "address": "2054 Jamestown Road, Williamsburg, VA, 23185",
    "description": "Das Auto’s at Billsburg Sunday, September 27th | 9a-Noon Located at Billsburg Brewery | 2054 Jamestown Rd, Williamsburg, VA, United States, 23185 Not just an event but a journey. Formaly known as Dubs at Billsburg, this event has been expanded to include all German car brands. This event is an extension of Billsburg's Octoberfest weekend and is a cruise-in style event with no entry fee and designed to bring all German car enthusiasts together. We are planning a couple meet ups starting on the peninsula at Huntington Beach at 10:00 am. From there we'll travel to Smithfield Plaza to meet up with southside cruisers and leave at 10:45 to head to the Jamestown Ferry. Will meet Richmond group at the ferry line at 11:15. Event will begin at Billsburg at 1200 noon. For groups, please plan your cruise from one of many great cruise routes including Rt 10, Rt 5, or colonial parkway. More Info",
