    "venue": "Coastal Community Church,",
    "address": "101 Village Avenue, Yorktown, VA, 23693",
    "description": "(Weekly) Classic Cruisers Saturday Night Cruz In Presented by Classic Cruisers Car Club Saturday, October 3rd | 4:30-8p Located at Coastal Community Church, 101 Village Ave., Yorktown. Mark your calendar to join us for our 1st Cruise-In. Cruz-Ins will be every Saturday from Apr 25 to Oct 24. All years and types of vehicles are welcome – If you believe it’s cool, bring it in. We are asking for a $2.00 donation per vehicle. Please consider donating more – All proceeds go to charity. Vehicles are to be parked as directed by club personnel when necessary. No bicycles, skateboards, scooters, roller blades, or anything used in a manner that could injure people or damage vehicles are allowed in the participant parking area. Please do not touch vehicles without owners’ permission. Children under 12 must be accompanied by an adult. No horseplay is allowed with vehicles at any time. (Such as burn-outs, engine revving, car hopping, loud radios or other disruptive actions). Alcoholic beverages, illegal drugs, and firearms are prohibited. There are to be NO SALES within the participant parking area EXCEPT for pre-approved items where the sale benefits charity. We are guests here. So PLEASE either take your trash with you or use the receptacles provided.",
