    "venue": "",
    "address": "East Virginia Beach Boulevard, Virginia Beach, VA",
    "description": "LBC Hope Foundation 2nd annual Show N Shine Sponsored by Sam's Club VB Saturday, October 24th | 11a-4p Located at 3345 Virginia Beach Blvd., Virginia Beach. Lock it in. The LBC Hope Foundation 2nd annual Show N Shine. Come out, show off your ride, meet amazing people and support a great Movement supporting CHKD Children’s Hospital. There will be Food Trucks, Music, Raffles and More. Classics, Imports, Muscle, Trucks/Jeeps & Motorcycles. Winners for 1st & 2nd each class, 1st & 2nd sound competition each class and Best of Show. Judged panel. Contestants will also get an entry into the Jeep Giveaway Mission in Motion at the sign in table to hold for the December 19th giveaway. Spectators will get a raffle ticket at entry. Support a Great Cause and CHKD Children's Hospital. Be around a great community who are all sharing the same passion. Most importantly coming together for a great Mission. LBC Hope Foundation is a 501c3 Non Profit Built on Mental Health & Chronic Illness Awareness that come together helping those in Need. We cant wait to see everyone out there. Register Here",
