    "description": "(1st Sat) Cars and Coffee Norfolk Goes to Chesapeake Saturday, November 7th | 9-11am Located at Greenbrier Mall, 1401 Greenbrier Pkwy., Chesapeake. Monthly car meet on the 1st Saturday of every month. All cars, motorcycles, bicycles, etc. welcome! Free coffee and doughnuts! ***UPDATE - New Location*** We're temporarily hosting our first Saturday events at Greenbrier Mall in Chesapeake. We will be in the lot behind the old Sears, at the back of the mall. As you enter, turn left and drive around the perimeter of the parking lot to the back where we'll be set up with the tent. Please be respectful of the temporary location and help us keep the event going. ABSOLUTELY NO: Revving, burnouts, loud music. Be on your best behavior and respect the location. More Info",
